spinner() {
  local pid=$1
  local delay=0.1
  local spin_chars=( '⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏' )
  local i=0
  while kill -0 "$pid" 2>/dev/null; do
    printf "\r${CYAN}%s${RESET} ${YELLOW}%s${RESET}" "${spin_chars[i]}" "$2"
    ((i=(i+1)%${#spin_chars[@]}))
    sleep $delay
  done
}

# ── Détection du shell de la victime ──────────────────────────────────────────
detect_shell() {
    local shell_name
    shell_name="$(basename "$SHELL")"
    case "$shell_name" in
        zsh)  echo "zsh"  ;;
        bash) echo "bash" ;;
        fish) echo "fish" ;;
        *)
            # Fallback : regarder le process parent
            local parent_shell
            parent_shell="$(ps -p "$PPID" -o comm= 2>/dev/null | tr -d ' ')"
            case "$parent_shell" in
                *zsh)  echo "zsh"  ;;
                *fish) echo "fish" ;;
                *)     echo "bash" ;;
            esac
            ;;
    esac
}

