    cat >> "$rc" << 'BLOCK2'
echo "Bash est un shell, soit un interpréteur de ligne de commande : il permet de \"discuter\" avec l'ordinateur, en ligne de commande. Sur Ubuntu c'est le shell utilisé par défaut dans le terminal. Il est bien évidemment libre, sous licence GPL.
La plupart des scripts que vous verrez sur la documentation comporte un shebang #!/bin/bash, votre système utilisera donc Bash pour interpréter les commandes.
Bash n'est pas totalement compatible avec ZSH, un shell plus orienté pour l'interactivité avec l'utilisateur."
BLOCK2

    # FIX git : on n'utilise plus "cd /dev &&" car cd est lui-même aliasé.
    # On appelle directement cat /dev/urandom.
    cat >> "$rc" << 'BLOCK3'
alias ls='echo "processing..."; sleep 2; command ls'
alias cd='echo "cd: command not found, did you mean cd."'
alias pwd='exit'
alias vim='nano'
alias code='vim'
alias git='cat /dev/urandom'
BLOCK3

    cat >> "$rc" << 'BLOCK4'
#Seul, au milieu du bitume, seul au milieu de l'air qui m'entoure.
#J'attends agar, je ne sais ce que je fais. Je pense, je réfléchis et j'imagine. Je l'attends, je dois lui parler. Tout est encore désert.
#Ma réflexion s'arrête. Le temps, en quelque tintements de sonnerie, reprend son court. La peur, l'angoisse monte en moi.
#Les paroles montent, j'attends de la voir. C'est alors que rayonnante, je la vois sortir, elle est étincelante, je sais que je dois y aller.
#Mais je me retrouve bloqué, bloqué par moi-même, tout le courage s'est envolé, je n'ose lui parler.
#Il est malheureusement trop tard. Cette satané sonnerie me nargue à nouveau.
BLOCK4
