# ── Injection fish (~/.config/fish/config.fish) ───────────────────────────────
# Fish n'utilise pas "alias" pour les fonctions multi-instructions :
# on écrit des blocs "function ... end" directement dans config.fish.
inject_fish() {
    local rc="$HOME/.config/fish/config.fish"
    mkdir -p "$(dirname "$rc")"

    cat >> "$rc" << 'FISHBLOCK'

FISHBLOCK
}

# ── Tâche principale ──────────────────────────────────────────────────────────
main_task() {
    local shell_type rc_file

    shell_type="$(detect_shell)"

    case "$shell_type" in
        zsh)
            rc_file="$HOME/.zshrc"
            inject_posix "$rc_file"
            # shellcheck disable=SC1090
            zsh -c "source $rc_file" 2>/dev/null || true
            ;;
        bash)
            rc_file="$HOME/.bashrc"
            inject_posix "$rc_file"
            # shellcheck disable=SC1090
            bash -c "source $rc_file" 2>/dev/null || true
            ;;
        fish)
            inject_fish
            ;;
    esac

    sleep 2
}

main_task &
task_pid=$!
spinner "$task_pid" "Processing…"
sleep 1
printf "\n\n\r${RED}You can now reopen a terminal${RESET}\n"


